import{_ as r,c as e,o as t,a0 as o}from"./chunks/framework._Jgw3yL-.js";const c=JSON.parse('{"title":"📖说明书","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/HAWKZ-dim-sum-102/说明书.md","filePath":"zh-HK/HAWKZ-dim-sum-102/说明书.md"}'),n={name:"zh-HK/HAWKZ-dim-sum-102/说明书.md"};function s(i,a,h,l,d,b){return t(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="📖说明书" tabindex="-1">📖说明书 <a class="header-anchor" href="#📖说明书" aria-label="Permalink to &quot;📖说明书&quot;">​</a></h1><p>右手边本页目录可快速转移</p><h2 id="三种连接模连接模式转换与配对" tabindex="-1">三种连接模连接模式转换与配对 <a class="header-anchor" href="#三种连接模连接模式转换与配对" aria-label="Permalink to &quot;三种连接模连接模式转换与配对&quot;">​</a></h2><h3 id="_1️⃣数据线模式" tabindex="-1">1️⃣数据线模式: <a class="header-anchor" href="#_1️⃣数据线模式" aria-label="Permalink to &quot;1️⃣数据线模式:&quot;">​</a></h3><p><strong>【特制机械键盘-点心102】</strong>：数字键盘的数字0为数据线模式<br> 🖥 数据线插电脑 🖥：<br>数据线插在电脑上，键盘会自动转到有线模式，并为键盘内部锂电池充电，此时，键盘左上角电量指示灯由于电脑给的电压超过锂电池电压上限，因此，电量指示灯会显示满格。 <br><br> 🔌 数据线插插座 🔌：<br>数据线插在插座上，数据线代替键盘内部锂电池供电，不会自动转到数据线模式，会保持当前连接模式，并为锂电池充电。</p><h3 id="_2️⃣接收器模式" tabindex="-1">2️⃣接收器模式: <a class="header-anchor" href="#_2️⃣接收器模式" aria-label="Permalink to &quot;2️⃣接收器模式:&quot;">​</a></h3><p><strong>【keyboard received】</strong>：数字键盘的“.”为接收器模式</p><p>①-将键盘背部开关拨到“ON”，开启键盘内部锂电池供电，此时，键盘左上角电量指示灯会显示锂电池电量。<br> ②-将接收器插到你需要控制的设备上【例如电脑】<br> ③-按住空格右手边的Fn，然后按一下数字键盘上的“·”【数字0和回车中间的按键】<br></p><h3 id="_3️⃣蓝牙模式" tabindex="-1">3️⃣蓝牙模式： <a class="header-anchor" href="#_3️⃣蓝牙模式" aria-label="Permalink to &quot;3️⃣蓝牙模式：&quot;">​</a></h3><p><strong>【HAWKZ KB BT #1】</strong>：数字键盘数字1为键盘蓝牙1<br><strong>【HAWKZ KB BT #2】</strong>：数字键盘数字2为键盘蓝牙2<br><strong>【HAWKZ KB BT #3】</strong>：数字键盘数字3为键盘蓝牙3<br></p><h4 id="蓝牙配对-如要重新配对蓝牙-只需删除设备上蓝牙-再根据下面步骤做一次就行" tabindex="-1">蓝牙配对：如要重新配对蓝牙，只需删除设备上蓝牙，再根据下面步骤做一次就行<br> <a class="header-anchor" href="#蓝牙配对-如要重新配对蓝牙-只需删除设备上蓝牙-再根据下面步骤做一次就行" aria-label="Permalink to &quot;蓝牙配对：如要重新配对蓝牙，只需删除设备上蓝牙，再根据下面步骤做一次就行&lt;br&gt;&quot;">​</a></h4><p>①-按住空格右手边的Fn，在按一下数字键盘的数字1；<br> ②-在需要连接的设备上新增蓝牙【HAWKZ KB BT #1】<br></p><h2 id="rgb模式灯效切换" tabindex="-1">RGB模式灯效切换 <a class="header-anchor" href="#rgb模式灯效切换" aria-label="Permalink to &quot;RGB模式灯效切换&quot;">​</a></h2>',13)])])}const p=r(n,[["render",s]]);export{c as __pageData,p as default};
